#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/binding/types/binding_contract_types.hpp"
#include "gui_forms/components/error_provider/error_provider_values/error_provider_values.hpp"
#include "gui_forms/types.hpp"

#include <chrono>
#include <cstdint>
#include <memory>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ErrorProvider's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/error_provider.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The icon's side in logical units, 8 to 64. A size outside that, or not finite, throws std::invalid_argument.
template <typename Declaring>
struct ErrorProviderIconSizeCapability {
    PropertyCell<double, ErrorProviderIconSizeCapability<Declaring>> icon_size{16.0};

    static void assign(ErrorProviderIconSizeCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.icon_size), incoming);
        if (!capability.icon_size.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.icon_size));
    }
};

// The blink interval, 50 ms to 1 minute (std::invalid_argument otherwise).
template <typename Declaring>
struct ErrorProviderBlinkRateCapability {
    PropertyCell<std::chrono::milliseconds, ErrorProviderBlinkRateCapability<Declaring>> blink_rate{250};

    static void assign(ErrorProviderBlinkRateCapability& capability, std::chrono::milliseconds incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.blink_rate), incoming);
        if (!capability.blink_rate.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.blink_rate));
    }
};

// When an icon blinks (see ErrorBlinkStyle). An unknown style throws std::invalid_argument.
template <typename Declaring>
struct ErrorProviderBlinkStyleCapability {
    PropertyCell<ErrorBlinkStyle, ErrorProviderBlinkStyleCapability<Declaring>> blink_style{ErrorBlinkStyle::blink_if_different_error};

    static void assign(ErrorProviderBlinkStyleCapability& capability, ErrorBlinkStyle incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.blink_style), incoming);
        if (!capability.blink_style.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.blink_style));
    }
};

// Whether icon alignments are mirrored. A change raises right_to_left_changed.
template <typename Declaring>
struct ErrorProviderRightToLeftCapability {
    PropertyCell<bool, ErrorProviderRightToLeftCapability<Declaring>> right_to_left{};

    static void assign(ErrorProviderRightToLeftCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.right_to_left), incoming);
        if (!capability.right_to_left.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.right_to_left));
    }
};

// The icon image, or none for the stock glyph. An image that is not live in the provider's window throws std::invalid_argument.
template <typename Declaring>
struct ErrorProviderIconCapability {
    PropertyCell<std::optional<ImageId>, ErrorProviderIconCapability<Declaring>> icon{};

    static void assign(ErrorProviderIconCapability& capability, std::optional<ImageId> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.icon), incoming);
        if (!capability.icon.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.icon));
    }
};

// The binding source whose errors the provider shows, or null; held weakly. A source that is not live or belongs to another window throws std::invalid_argument. An unchanged write updates the binding.
template <typename Declaring>
struct ErrorProviderDataSourceCapability {
    PropertyView<std::shared_ptr<BindingSource>, ErrorProviderDataSourceCapability<Declaring>> data_source;

    static void assign(ErrorProviderDataSourceCapability& capability, std::shared_ptr<BindingSource> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.data_source), std::move(incoming));
    }

    static std::shared_ptr<BindingSource> read(const ErrorProviderDataSourceCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::shared_ptr<BindingSource> current = control.read_view(capability.data_source);
        return current;
    }
};

// The member of the data source whose errors the provider shows, canonicalized; empty for the source's own. A name that is not valid UTF-8 throws std::invalid_argument.
template <typename Declaring>
struct ErrorProviderDataMemberCapability {
    PropertyCell<std::string, ErrorProviderDataMemberCapability<Declaring>> data_member{};

    static void assign(ErrorProviderDataMemberCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.data_member), incoming);
        if (!capability.data_member.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.data_member));
    }
};

// Every ErrorProvider capability, in the order the declaring class takes them.
template <typename Declaring>
struct ErrorProviderCapabilities : public ErrorProviderIconSizeCapability<Declaring>,
                                   public ErrorProviderBlinkRateCapability<Declaring>,
                                   public ErrorProviderBlinkStyleCapability<Declaring>,
                                   public ErrorProviderRightToLeftCapability<Declaring>,
                                   public ErrorProviderIconCapability<Declaring>,
                                   public ErrorProviderDataSourceCapability<Declaring>,
                                   public ErrorProviderDataMemberCapability<Declaring> {};

} // namespace gui_forms
